import { __ } from '@wordpress/i18n';
import { BaseControl, Button, ColorPalette } from '@wordpress/components';

const JoliColorPicker = ( { label, value, onChange } ) => {
    return (
        <BaseControl className="wpj-jtoc--color-picker-control">
            <div className="wpj-jtoc--label-container">
                <label>{label}</label>
            </div>
            <ColorPalette
                // colors={colors}
                className="wpj-jtoc--color-picker"
                value={value}
                onChange={( val ) => onChange( val )}
                clearable={typeof value !== 'undefined'}
                enableAlpha
            />
            {typeof value !== 'undefined' &&
                <div style={{ overflow: 'auto' }} >
                    <Button
                        style={{ "float": "right" }}
                        isSmall
                        variant={'link'}
                        // variant="link"
                        onClick={() => onChange()}
                    >{__( 'Clear', 'joli-table-of-contents' )}</Button>
                </div>
            }
        </BaseControl>
    );
}

export default JoliColorPicker;

