import { Icon } from '@wordpress/components';

const JoliFaqToggleIcon = ( { iconClass } ) => {
    return (
        <Icon
            icon={() => (
                <div className="jtoc-wrap">
                    <div className={"jtoc--group --jtoc-theme-x " + iconClass}>
                        <div className="jtoc--toggle-wrap">
                            <div className="jtoc--toggle"></div>
                        </div>
                    </div>
                </div>
            )}
        />
    );
}

export default JoliFaqToggleIcon;

